//! Composition (design: Layers): which entries apply to some agents in one place, in what order, and where
//! each output line comes from. Harness-neutral: adapters (adapters.rs) decide where the text goes.

use crate::model::{Audience, Entry, Kind, Scope, Visibility};
use crate::stack::Stacks;
use serde::Serialize;
use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

pub const BEGIN: &str = "<!-- lords-command:begin -->";
pub const END: &str = "<!-- lords-command:end -->";
const HEADER: &str =
    "<!-- Generated by Lords Command from its stacks; change an entry there, then sync. -->";

const MEMORY_INTRO: &str = "Notes agents wrote down earlier. Read a note's file when its topic comes up; notes are not rules.";

/// The line that stands for notes meant for one role, when the reader's role is unknown: how many per role, and
/// the dirs they are in.
fn role_pointer(notes: &[&Entry], ctx: &Context) -> Option<String> {
    if notes.is_empty() {
        return None;
    }
    let mut counts: std::collections::BTreeMap<&str, usize> = std::collections::BTreeMap::new();
    let mut dirs: Vec<String> = Vec::new();
    for e in notes {
        for r in &e.meta.roles {
            *counts.entry(r.as_str()).or_default() += 1;
        }
        let dir = e.body_file.parent().map(|d| shown(d, ctx)).unwrap_or_default();
        if !dirs.contains(&dir) {
            dirs.push(dir);
        }
    }
    let counts: Vec<String> =
        default_first(counts, ctx).iter().map(|(r, n)| format!("{r}: {n}")).collect();
    let dirs: Vec<String> = dirs.iter().map(|d| format!("`{d}`")).collect();
    Some(format!(
        "- More notes are for one role only ({}); in that role, find them in {} (each file's `roles` says whose).",
        counts.join(", "),
        dirs.join(", ")
    ))
}

const INTENT_INTRO: &str =
    "The owner's intent, binding. Read an entry's file before work its subject touches; the file is the full text.";

/// The longest hook an index line shows; the file it points to has the whole description.
pub const HOOK_CHARS: usize = 100;

/// A hook cut at a word boundary to at most `HOOK_CHARS` characters, with "…" when cut.
fn short_hook(hook: &str) -> String {
    if hook.chars().count() <= HOOK_CHARS {
        return hook.to_string();
    }
    let cut: String = hook.chars().take(HOOK_CHARS).collect();
    let at_word =
        cut.rfind(' ').filter(|i| *i > HOOK_CHARS / 2).map_or(cut.as_str(), |i| &cut[..i]);
    format!("{}…", at_word.trim_end_matches([',', ';', ':', ' ', '-', '—']))
}

/// A path as composed text shows it: the platform's separators, and relative to `relative_to` when the context
/// sets it (the one switch to relative paths, once a harness is shown to resolve them; docs/load-order.md).
fn shown(p: &Path, ctx: &Context) -> String {
    let rel = ctx.relative_to.as_deref().and_then(|base| relative(p, base));
    let path = rel.as_deref().unwrap_or(p).to_string_lossy().into_owned();
    if cfg!(windows) {
        path.replace('/', "\\")
    } else {
        path
    }
}

/// `p` from `base` (`..` up to their common dir), or `None` when they share no root (another drive).
fn relative(p: &Path, base: &Path) -> Option<PathBuf> {
    use std::path::Component;
    let key = |c: Component| {
        let s = c.as_os_str().to_string_lossy().into_owned();
        if cfg!(windows) {
            s.to_lowercase()
        } else {
            s
        }
    };
    let (a, b): (Vec<Component>, Vec<Component>) =
        (p.components().collect(), base.components().collect());
    let common = a.iter().zip(&b).take_while(|(x, y)| key(**x) == key(**y)).count();
    if common == 0 {
        return None;
    }
    let mut out = PathBuf::new();
    for _ in common..b.len() {
        out.push("..");
    }
    for c in &a[common..] {
        out.push(c.as_os_str());
    }
    Some(if out.as_os_str().is_empty() { PathBuf::from(".") } else { out })
}

/// Where an index line's file is: the dir its group names once, and the file's path within it. A skill's file is
/// `<name>/SKILL.md` in its skills dir; any other entry's is its file name in its own dir.
fn index_place(e: &Entry) -> (PathBuf, PathBuf) {
    let file = &e.body_file;
    let up = if e.meta.kind == Kind::Skill { 2 } else { 1 };
    let mut dir = file.as_path();
    for _ in 0..up {
        dir = dir.parent().unwrap_or(dir);
    }
    (dir.to_path_buf(), file.strip_prefix(dir).unwrap_or(file).to_path_buf())
}

/// An index entry's display name, when its file follows from it (a note's `<name>.md`, a skill's
/// `<name>/SKILL.md`).
fn named_file(e: &Entry, name: &str) -> PathBuf {
    match e.meta.kind {
        Kind::Skill => Path::new(name).join("SKILL.md"),
        _ => PathBuf::from(format!("{name}.md")),
    }
}

/// Index lines grouped by dir: each dir is named once ("In `<dir>`:"), each line ends with its file within it, or
/// with nothing when its name gives the file (the group line says how). `items`: the entry and the line's text.
fn push_index(
    items: &[(&Entry, String, Option<String>)],
    ctx: &Context,
    lines: &mut Vec<String>,
    out: &mut Composed,
) {
    let mut current: Option<PathBuf> = None;
    for (i, (e, text, name)) in items.iter().enumerate() {
        let (dir, file) = index_place(e);
        if current.as_ref() != Some(&dir) {
            let named = |x: &(&Entry, String, Option<String>)| {
                x.2.as_deref()
                    .is_some_and(|n| index_place(x.0) == (dir.clone(), named_file(x.0, n)))
            };
            let rest = &items[i..];
            let group = rest.iter().take_while(|x| index_place(x.0).0 == dir);
            let how = if group.clone().any(named) {
                let pattern = match e.meta.kind {
                    Kind::Skill => shown(&Path::new("<name>").join("SKILL.md"), ctx),
                    _ => "<name>.md".to_string(),
                };
                format!(", as `{pattern}`")
            } else {
                String::new()
            };
            lines.push(format!("In `{}`{how}:", shown(&dir, ctx)));
            current = Some(dir.clone());
        }
        let follows = name.as_deref().is_some_and(|n| named_file(e, n) == file);
        if follows {
            lines.push(format!("- {text}"));
        } else {
            lines.push(format!("- {text} (`{}`)", shown(&file, ctx)));
        }
        out.sources.push(Source {
            line: lines.len(),
            id: e.id().to_string(),
            stack: e.stack,
            file: e.body_file.clone(),
            file_line: 1,
        });
        out.ids.push(e.id().to_string());
    }
}

/// Memory or skill index entries, each with its line's text and the name its file may follow from.
fn index_items<'e>(entries: &[&'e Entry]) -> Vec<(&'e Entry, String, Option<String>)> {
    entries
        .iter()
        .map(|e| {
            let (name, text) = index_item(e);
            (*e, text, Some(name))
        })
        .collect()
}

/// The line that stands for everything for only some roles in a place's file: each role's file carries it in
/// full; how many entries and notes each has.
fn role_files_line(pointed: &[&Entry], dir: &Path, ctx: &Context) -> String {
    let mut counts: std::collections::BTreeMap<&str, usize> = std::collections::BTreeMap::new();
    for e in pointed {
        for r in &e.meta.roles {
            *counts.entry(r.as_str()).or_default() += 1;
        }
    }
    let files: Vec<String> = default_first(counts, ctx)
        .iter()
        .map(|(r, n)| {
            let here = if ctx.default_role.as_deref() == Some(*r) {
                ", the default role here"
            } else {
                ""
            };
            format!("`{}` ({n}{here})", crate::sync::role_file(r))
        })
        .collect();
    format!(
        "More rules, facts, status and notes bind only some roles; each role's file in `{}` has them in full: {}.",
        shown(dir, ctx),
        files.join(", ")
    )
}

/// A memory or skill index entry: its name and the line's text (name and one-line hook).
fn index_item(e: &Entry) -> (String, String) {
    // A skill's own SKILL.md frontmatter names and describes it, as the harness shows it.
    let own = |key: &str| -> Option<String> {
        let yaml = crate::frontmatter::split(&e.body).yaml?;
        yaml.lines().find_map(|l| {
            l.strip_prefix(key)
                .and_then(|rest| rest.strip_prefix(':'))
                .map(|v| v.trim().trim_matches(['"', '\'']).to_string())
        })
    };
    let skill = e.meta.kind == Kind::Skill;
    let name = e
        .meta
        .name
        .clone()
        .or_else(|| skill.then(|| own("name")).flatten())
        .unwrap_or_else(|| e.id().trim_start_matches("memory.").to_string());
    let described =
        e.meta.description.clone().or_else(|| skill.then(|| own("description")).flatten());
    let hook = short_hook(described.as_deref().unwrap_or(&e.meta.title));
    let text = if hook.trim().is_empty() || hook == name {
        name.clone()
    } else {
        format!("{name}: {hook}")
    };
    (name, text)
}

/// Kinds composed into instruction text, in section order.
const SECTIONS: [(Kind, &str); 5] = [
    (Kind::Intent, "Owner intent"),
    (Kind::Role, "Roles"),
    (Kind::Rule, "Rules"),
    (Kind::Fact, "Facts"),
    (Kind::Status, "Status"),
];

/// Which layers a composition takes.
#[derive(Clone, Debug)]
pub enum Layers {
    /// User-level files, which every run on the machine reads (product turns too, backbone requirement BB-5): only global entries
    /// for every role, and no memory. See `user_level`.
    Global,
    /// A repo's own files: its project, the repo, path entries covering `sub`, and the global entries the user
    /// level leaves out (role-specific ones and memory). With `global`, every global entry (a file that must
    /// stand alone: a tracked AGENTS.md, a role file a brief points to).
    Repo { repo: String, project: Option<String>, sub: Option<String>, global: bool },
    /// A working dir with no git repo (e.g. a harness dir): like a repo, with its own workspace layer.
    Workspace { name: String, project: Option<String>, global: bool },
}

/// Whether an entry suits every run on the machine, so it may go to user-level files and skill dirs: a global
/// entry for every role (no `roles`) that is no memory note. A skill with roles installs per checkout instead.
pub fn user_level(e: &Entry) -> bool {
    matches!(e.scope, Scope::Global) && e.meta.roles.is_empty() && e.meta.kind != Kind::Memory
}

#[derive(Clone, Debug)]
pub struct Context {
    pub audience: Vec<Audience>,
    pub layers: Layers,
    /// Only entries from the public stack (a tracked file anyone can read).
    pub public_only: bool,
    /// Memory stores the target's harness already loads by itself: left out of the memory index.
    pub skip_stores: Vec<String>,
    /// The role whoever reads the file has (`None`: unknown). A known role gets only entries for it (or for
    /// every role); with an unknown one, role-specific entries are labelled, and role-specific notes are left out
    /// of the memory index for a pointer to them.
    pub roles: Option<Vec<String>>,
    /// For files every role reads whole, under a byte limit for some harnesses (a place's agent files): owner
    /// intent, and entries for only some roles, as index lines (title and file, read on demand) instead of their
    /// text. Role files and user-level files carry the text.
    pub by_reference: bool,
    /// With `by_reference`, the dir of this place's role files: entries and notes for only some roles are then
    /// left out for one line that points there (each role file carries them in full).
    pub role_dir: Option<PathBuf>,
    /// Paths shown relative to this dir instead of absolute (see `shown`).
    pub relative_to: Option<PathBuf>,
    /// With `role_dir`, the role a reader without a brief has (the place's `default_role`): with
    /// `default_role_inline` its entries and notes stay inline, labelled; without, they go behind the role-files
    /// line like the others', and that line (and the notes line) names this role first.
    pub default_role: Option<String>,
    /// Whether the adapter's file carries the default role inline (`Adapter::default_role_inline`).
    pub default_role_inline: bool,
}

impl Context {
    /// The default role, where its entries and notes stay inline.
    fn inline_role(&self) -> Option<&String> {
        self.default_role.as_ref().filter(|_| self.default_role_inline && self.role_dir.is_some())
    }
}

/// Roles and their counts, the default role first, then by name.
fn default_first<'a>(
    counts: std::collections::BTreeMap<&'a str, usize>,
    ctx: &Context,
) -> Vec<(&'a str, usize)> {
    let mut v: Vec<(&str, usize)> = counts.into_iter().collect();
    v.sort_by_key(|(r, _)| ctx.default_role.as_deref() != Some(*r));
    v
}

#[derive(Clone, Debug, Serialize)]
pub struct Source {
    /// 1-based line in the composed text.
    pub line: usize,
    pub id: String,
    pub stack: Visibility,
    pub file: PathBuf,
    pub file_line: usize,
}

#[derive(Clone, Debug, Default)]
pub struct Composed {
    /// The block, markers included; empty when nothing applies.
    pub text: String,
    pub sources: Vec<Source>,
    /// Ids composed, in order.
    pub ids: Vec<String>,
    /// Ids dropped because an applicable entry overrides them.
    pub overridden: Vec<String>,
    /// Applicable skills (installed as links, not composed into text).
    pub skills: Vec<String>,
}

fn in_layers(e: &Entry, layers: &Layers) -> bool {
    scope_in_layers(&e.scope, layers, user_level(e))
}

/// Whether something of `scope` belongs in `layers`; `user_level`: it suits every run (see `user_level`).
fn scope_in_layers(scope: &Scope, layers: &Layers, user_level: bool) -> bool {
    match (layers, scope) {
        (Layers::Global, _) => user_level,
        (Layers::Workspace { project, .. }, Scope::Project(p)) => project.as_deref() == Some(p),
        (Layers::Workspace { name, .. }, Scope::Workspace(w)) => w == name,
        (Layers::Workspace { global, .. }, Scope::Global) => *global || !user_level,
        (Layers::Workspace { .. }, _) => false,
        (Layers::Repo { project, .. }, Scope::Project(p)) => project.as_deref() == Some(p),
        (Layers::Repo { repo, .. }, Scope::Repo(r)) => r == repo,
        (Layers::Repo { repo, sub, .. }, Scope::Path { repo: r, sub: s }) => {
            r == repo
                && sub
                    .as_deref()
                    .is_some_and(|here| here == s || here.starts_with(&format!("{s}/")))
        }
        (Layers::Repo { global, .. }, Scope::Global) => *global || !user_level,
        (Layers::Repo { .. }, Scope::Workspace(_)) => false,
    }
}

fn reaches(e: &Entry, audience: &[Audience]) -> bool {
    e.meta.audience.contains(&Audience::All) || e.meta.audience.iter().any(|a| audience.contains(a))
}

/// The label for an entry meant for only some of a target's audiences (Sol and Astra share one file).
/// The label for an entry meant for only some of a file's readers: the agents (Sol and Astra share one file)
/// and, where the file's role is unknown, the roles.
/// The role that product runs have (backbone requirement BB-4). Place files never reach product runs (BB-5), so an entry for every
/// other role needs no role label there.
pub const PRODUCT_ROLE: &str = "product";

fn only_for(e: &Entry, ctx: &Context, development: &[String]) -> Option<String> {
    let mut parts = Vec::new();
    if let Some(agents) = only_agents(e, &ctx.audience) {
        parts.push(agents);
    }
    let every_development_role =
        !development.is_empty() && development.iter().all(|r| e.meta.roles.contains(r));
    if ctx.roles.is_none() && !e.meta.roles.is_empty() && !every_development_role {
        parts.push(e.meta.roles.join(", "));
    }
    (!parts.is_empty()).then(|| parts.join("; "))
}

fn only_agents(e: &Entry, audience: &[Audience]) -> Option<String> {
    if e.meta.audience.contains(&Audience::All)
        || audience.iter().all(|a| e.meta.audience.contains(a))
    {
        return None;
    }
    let names: Vec<&str> = e
        .meta
        .audience
        .iter()
        .filter(|a| audience.contains(a))
        .map(|a| match a {
            Audience::Opus => "Opus",
            Audience::Sol => "Sol",
            Audience::Astra => "Astra",
            Audience::All => "all",
        })
        .collect();
    Some(names.join(", "))
}

pub fn applicable<'a>(stacks: &'a Stacks, ctx: &Context) -> Vec<&'a Entry> {
    let today = crate::ops::today();
    stacks
        .entries()
        .filter(|e| e.active())
        .filter(|e| !ctx.public_only || e.stack == Visibility::Public)
        .filter(|e| in_layers(e, &ctx.layers) && reaches(e, &ctx.audience))
        .filter(|e| for_role(e, ctx))
        // An ended temporary entry is never composed (it is retired at the next sync).
        .filter(|e| crate::temporary::ended(e, stacks, &today).is_none())
        .collect()
}

/// A known role takes entries for it or for every role; an unknown one keeps them all (labelled, or pointed to).
fn for_role(e: &Entry, ctx: &Context) -> bool {
    match &ctx.roles {
        None => true,
        // A note for every role is a development note: product runs get none (orchestrator, 25 Oct).
        Some(roles) if e.meta.roles.is_empty() => {
            e.meta.kind != Kind::Memory || roles.iter().any(|r| r != PRODUCT_ROLE)
        }
        Some(roles) => e.meta.roles.iter().any(|r| roles.contains(r)),
    }
}

pub fn compose(stacks: &Stacks, ctx: &Context) -> Composed {
    let mut development: Vec<String> = stacks
        .all()
        .flat_map(|s| s.manifest.roles.iter())
        .filter(|r| *r != PRODUCT_ROLE)
        .cloned()
        .collect();
    development.sort();
    development.dedup();
    let all = applicable(stacks, ctx);
    let overridden: BTreeSet<&str> =
        all.iter().flat_map(|e| e.meta.overrides.iter().map(String::as_str)).collect();
    let live: Vec<&Entry> = all.into_iter().filter(|e| !overridden.contains(e.id())).collect();
    // For only some of the development roles, where the reader's role is unknown.
    let partial_role = |e: &Entry| {
        ctx.roles.is_none()
            && !e.meta.roles.is_empty()
            && !development.iter().all(|r| e.meta.roles.contains(r))
    };
    // Where role files exist, their entries and notes stay there: one line points to them (orchestrator, 25 Oct:
    // cut "index lines that the role files already carry in full").
    let (pointed, live): (Vec<&Entry>, Vec<&Entry>) = match &ctx.role_dir {
        Some(_) if ctx.by_reference => live.into_iter().partition(|e| {
            partial_role(e)
                && !matches!(e.meta.kind, Kind::Intent | Kind::Skill)
                && !ctx.inline_role().is_some_and(|d| e.meta.roles.contains(d))
        }),
        _ => (Vec::new(), live),
    };
    let mut out = Composed {
        overridden: overridden.iter().map(|s| s.to_string()).collect(),
        skills: live
            .iter()
            .filter(|e| e.meta.kind == Kind::Skill)
            .map(|e| e.id().to_string())
            .collect(),
        ..Composed::default()
    };
    let ids: BTreeSet<&str> = live.iter().map(|e| e.id()).collect();
    fn extension_of<'e>(e: &'e Entry, ids: &BTreeSet<&str>) -> Option<&'e str> {
        e.meta.extends.first().map(String::as_str).filter(|t| ids.contains(t))
    }

    let mut lines: Vec<String> = Vec::new();
    if let (Some(dir), false) = (&ctx.role_dir, pointed.is_empty()) {
        lines.push(role_files_line(&pointed, dir, ctx));
    }
    let push_entry = |e: &Entry, lines: &mut Vec<String>, out: &mut Composed| {
        let who = only_for(e, ctx, &development);
        let temp = crate::temporary::label(e, stacks);
        // In a file every role reads under a byte limit, an entry for only some roles is a reference; the role
        // files of the roles it binds carry its text.
        let inline_here =
            ctx.role_dir.is_some() && ctx.inline_role().is_some_and(|d| e.meta.roles.contains(d));
        if ctx.by_reference && partial_role(e) && !inline_here {
            let who = who.unwrap_or_else(|| e.meta.roles.join(", "));
            let temp = temp.map(|t| format!("; {t}")).unwrap_or_default();
            let path = shown(&e.body_file, ctx);
            lines.push(format!("- ({who} only{temp}) {} (`{path}`)", e.meta.title));
            out.sources.push(Source {
                line: lines.len(),
                id: e.id().to_string(),
                stack: e.stack,
                file: e.body_file.clone(),
                file_line: e.body_line,
            });
            out.ids.push(e.id().to_string());
            return;
        }
        match (who, temp) {
            (Some(who), Some(t)) => lines.push(format!("({who} only; {t})")),
            (Some(who), None) => lines.push(format!("({who} only)")),
            (None, Some(t)) => lines.push(format!("({t})")),
            (None, None) => {}
        }
        for (i, l) in e.body.trim_matches('\n').lines().enumerate() {
            lines.push(l.trim_end_matches('\r').to_string());
            out.sources.push(Source {
                line: lines.len(),
                id: e.id().to_string(),
                stack: e.stack,
                file: e.body_file.clone(),
                file_line: e.body_line + i,
            });
        }
        out.ids.push(e.id().to_string());
    };

    for (kind, heading) in SECTIONS {
        let mut section: Vec<&Entry> = live
            .iter()
            .copied()
            .filter(|e| e.meta.kind == kind && extension_of(e, &ids).is_none())
            .collect();
        if section.is_empty() {
            continue;
        }
        section.sort_by(|a, b| {
            (a.rank(), a.meta.order.unwrap_or(0), a.id()).cmp(&(
                b.rank(),
                b.meta.order.unwrap_or(0),
                b.id(),
            ))
        });
        if !lines.is_empty() {
            lines.push(String::new());
        }
        lines.push(format!("# {heading}"));
        if kind == Kind::Intent && ctx.by_reference {
            lines.push(String::new());
            lines.push(INTENT_INTRO.into());
            lines.push(String::new());
            let mut items = Vec::new();
            for e in section {
                let mut ext: Vec<&Entry> = live
                    .iter()
                    .copied()
                    .filter(|x| extension_of(x, &ids) == Some(e.id()))
                    .collect();
                ext.sort_by_key(|x| x.id().to_string());
                for x in std::iter::once(e).chain(ext) {
                    let temp = crate::temporary::label(x, stacks)
                        .map(|t| format!(" ({t})"))
                        .unwrap_or_default();
                    items.push((x, format!("{}{temp}", x.meta.title), None));
                }
            }
            push_index(&items, ctx, &mut lines, &mut out);
            continue;
        }
        for e in section {
            lines.push(String::new());
            push_entry(e, &mut lines, &mut out);
            // Extensions follow the entry they extend, in id order.
            let mut ext: Vec<&Entry> =
                live.iter().copied().filter(|x| extension_of(x, &ids) == Some(e.id())).collect();
            ext.sort_by_key(|x| x.id().to_string());
            for x in ext {
                push_entry(x, &mut lines, &mut out);
            }
        }
    }
    // The skills of this place: the repo's own (backbone requirement BB-8, listed where they are) and the stack's development
    // skills (installed per checkout for harnesses that read a skills dir); listed so every harness finds them.
    let here: Vec<&Entry> = live
        .iter()
        .copied()
        .filter(|e| {
            e.meta.kind == Kind::Skill
                && (matches!(e.meta.origin, crate::model::Origin::InRepo { .. }) || !user_level(e))
        })
        .collect();
    if !here.is_empty() {
        if !lines.is_empty() {
            lines.push(String::new());
        }
        lines.push("# Skills here".into());
        lines.push(String::new());
        push_index(&index_items(&here), ctx, &mut lines, &mut out);
    }
    // Memory: an index, not text. Each harness reads the notes on demand (docs/load-order.md); a note binds
    // nobody until it is promoted to an intent, rule or fact.
    let mut notes: Vec<&Entry> = live
        .iter()
        .copied()
        .filter(|e| e.meta.kind == Kind::Memory)
        .filter(|e| match &e.meta.origin {
            crate::model::Origin::Imported { store, .. } => !ctx.skip_stores.contains(store),
            _ => true,
        })
        .collect();
    // A live store's index is the file its agents write, one source (orchestrator, 30 Oct, item 3): it is named once,
    // and its imported copies, which lag until the next import, are left out.
    let live: Vec<&crate::stack::MemoryStore> = stacks
        .private
        .iter()
        .flat_map(|p| p.manifest.memory_stores.iter())
        .filter(|m| m.live)
        .collect();
    let store_of = |e: &Entry| match &e.meta.origin {
        crate::model::Origin::Imported { store, .. } => {
            live.iter().copied().find(|m| m.name == *store)
        }
        _ => None,
    };
    // Named from its declaration wherever its scope and audience reach and its harness doesn't load it by itself, so
    // a store with no note imported yet is named too (sol-loop r1, S1).
    let serves = |m: &crate::stack::MemoryStore| {
        m.audience.is_empty()
            || m.audience.iter().any(|a| {
                a == "all" || ctx.audience.iter().any(|c| format!("{c:?}").eq_ignore_ascii_case(a))
            })
    };
    let live_here: BTreeSet<(&str, String)> = live
        .iter()
        .copied()
        .filter(|m| Scope::parse(&m.scope).is_some_and(|s| scope_in_layers(&s, &ctx.layers, false)))
        .filter(|m| serves(m) && !ctx.skip_stores.contains(&m.name))
        .map(|m| {
            let index = crate::config::expand_home(&m.path).join("MEMORY.md");
            (
                m.name.as_str(),
                index.display().to_string().replace('/', std::path::MAIN_SEPARATOR_STR),
            )
        })
        .collect();
    notes.retain(|e| store_of(e).is_none());
    notes.sort_by(|a, b| (a.rank(), a.id()).cmp(&(b.rank(), b.id())));
    // Where the reader's role is unknown, notes for one role stay out of the index; one line says where they are.
    // The place's default role is no unknown one: its notes stay in the index.
    let default_note = |e: &Entry| {
        ctx.role_dir.is_some() && ctx.inline_role().is_some_and(|d| e.meta.roles.contains(d))
    };
    let (role_notes, notes): (Vec<&Entry>, Vec<&Entry>) = notes
        .into_iter()
        .partition(|e| ctx.roles.is_none() && !e.meta.roles.is_empty() && !default_note(e));
    let pointer = role_pointer(&role_notes, ctx);
    if !notes.is_empty() || pointer.is_some() || !live_here.is_empty() {
        if !lines.is_empty() {
            lines.push(String::new());
        }
        lines.push("# Memory".into());
        lines.push(String::new());
        lines.push(MEMORY_INTRO.into());
        lines.push(String::new());
        for (name, index) in &live_here {
            lines.push(format!("- {name}: its index is `{index}`, which its agents keep current"));
        }
        push_index(&index_items(&notes), ctx, &mut lines, &mut out);
        if let Some(p) = pointer {
            lines.push(p);
        }
    }
    if out.ids.is_empty() && lines.is_empty() {
        return out;
    }
    // Two header lines precede the composed lines.
    for s in out.sources.iter_mut() {
        s.line += 2;
    }
    let mut text = format!("{BEGIN}\n{HEADER}\n");
    text.push_str(&lines.join("\n"));
    text.push('\n');
    text.push_str(END);
    text.push('\n');
    out.text = text;
    out
}

/// A managed block holding `body` (e.g. one include line).
pub fn block(body: &str) -> String {
    format!("{BEGIN}\n{HEADER}\n{}\n{END}\n", body.trim_end())
}

/// A composed block with `pre` first, right after the header (a repo file's tracked-instructions line).
pub fn with_preamble(text: &str, pre: &str) -> String {
    let head = format!("{BEGIN}\n{HEADER}\n");
    match text.strip_prefix(&head) {
        Some(rest) => format!("{head}{}\n\n{rest}", pre.trim_end()),
        None => format!("{}\n\n{text}", pre.trim_end()),
    }
}

/// Where a file's managed block is: from the start of its begin-marker line to the end of its end-marker line's
/// text, before that line's own line ending. Markers count only as whole lines (a sentence quoting one is owner
/// text). Anything but one begin line before one end line is an error: the file is no longer ours to edit.
fn block_span(text: &str) -> Result<Option<(usize, usize)>, String> {
    let (mut begins, mut ends) = (Vec::new(), Vec::new());
    let mut at = 0;
    for line in text.split_inclusive('\n') {
        let content = line.trim_end_matches('\n').trim_end_matches('\r');
        // A byte-order mark before the first line belongs to the owner's text, not to the marker.
        let bom =
            if at == 0 && content.starts_with('\u{feff}') { '\u{feff}'.len_utf8() } else { 0 };
        let content = &content[bom..];
        if content == BEGIN {
            begins.push(at + bom);
        }
        if content == END {
            ends.push(at + bom + content.len());
        }
        at += line.len();
    }
    match (begins.as_slice(), ends.as_slice()) {
        ([], []) => Ok(None),
        ([b], [e]) if b < e => Ok(Some((*b, *e))),
        _ => Err(format!(
            "{} begin and {} end marker lines, not one managed block; fix the file by hand, sync leaves it alone",
            begins.len(),
            ends.len()
        )),
    }
}

/// Puts a block into a file's text: between its marker lines, else appended. `replace` drops the text outside.
/// Every byte outside the block stays as it was, the line ending after the end marker (or its absence) included.
/// An error when the file's markers are broken, or the block itself carries marker lines (a quoted tracked file).
pub fn place_block(current: &str, block: &str, replace: bool) -> Result<String, String> {
    if !block.is_empty() && block_span(block)?.is_none() {
        return Err("the composed block has no marker lines".into());
    }
    if replace {
        return Ok(block.to_string());
    }
    if let Some((b, e)) = block_span(current)? {
        let after = &current[e..];
        // Removing the block keeps every byte around it, the end marker's own line ending included (Sol review
        // r2, R2-18).
        if block.is_empty() {
            return Ok(format!("{}{after}", &current[..b]));
        }
        let body = block.strip_suffix('\n').unwrap_or(block);
        return Ok(format!("{}{body}{after}", &current[..b]));
    }
    if block.is_empty() || current.is_empty() {
        return Ok(format!("{current}{block}"));
    }
    let sep = if current.ends_with("\n\n") {
        ""
    } else if current.ends_with('\n') {
        "\n"
    } else {
        "\n\n"
    };
    Ok(format!("{current}{sep}{block}"))
}

/// The managed block currently in a file, if it has exactly one.
pub fn current_block(text: &str) -> Option<&str> {
    let (b, e) = block_span(text).ok()??;
    let after = &text[e..];
    let nl = if after.starts_with("\r\n") {
        2
    } else if after.starts_with('\n') {
        1
    } else {
        0
    };
    Some(&text[b..e + nl])
}
